        private void BindButton(
            Fgui.GComponent root,
            string childName,
            string label,
            bool enabled,
            string commandId,
            Func<object> payloadFactory,
            bool selected = false,
            bool checkMode = false)
        {
            Fgui.GButton button = root.GetChild(childName)?.asButton;
            if (button == null)
                return;

            if (checkMode)
                button.mode = Fgui.ButtonMode.Check;
            button.text = label ?? string.Empty;
            button.enabled = enabled;
            button.grayed = !enabled;
            button.selected = selected;
            button.visible = true;
            button.onClick.Set(() =>
            {
                if (!enabled)
                    return;

                object payload = payloadFactory != null ? payloadFactory() : null;
                _commandSink?.Enqueue(new MxUiCommand(_viewId, commandId, payload));
            });
        }

        private static void BindText(Fgui.GComponent root, string childName, string value)
        {
            Fgui.GTextField text = root.GetChild(childName)?.asTextField;
            if (text != null)
                text.text = value ?? string.Empty;
        }

        private static void BindInput(Fgui.GComponent root, string childName, string value)
        {
            Fgui.GTextField input = root.GetChild(childName)?.asTextField;
            if (input == null)
                return;

            if (!Application.isPlaying || !input.focused)
                input.text = value ?? string.Empty;

            Fgui.GTextInput textInput = input as Fgui.GTextInput;
            if (textInput != null)
                textInput.editable = true;
        }

        private static string ReadText(Fgui.GComponent root, string childName, string fallback)
        {
            Fgui.GObject child = root.GetChild(childName);
            Fgui.GTextField text = child != null ? child.asTextField : null;
            if (text == null)
                return fallback;

            return string.IsNullOrWhiteSpace(text.text) ? fallback : text.text.Trim();
        }

